pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        require(_tos.length > 0, "empty tos");
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length <= 10);
        for (uint i = 0; i < _tos.length; i++) {
            _tos[i] = address(uint160(bound(uint256(uint160(_tos[i])), 1, type(uint160).max)));
            v[i] = bound(v[i], 0, type(uint256).max);
        }
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = true;
            assertTrue(ret, "return value must be true when call does not revert");
        } catch {
            ok = false;
        }
    }
}

